SELECT CASE WHEN credit_limit >= 17000 THEN 'high' WHEN credit_limit >= 6900 THEN 'mid' ELSE 'low' END credit_limit_bucket, DATE_TRUNC('MONTH', signup_date) signup_month, MAX(credit_limit) - MIN(credit_limit) credit_limit_range, MIN(signup_date) min_signup_date FROM customers GROUP BY CASE WHEN credit_limit >= 17000 THEN 'high' WHEN credit_limit >= 6900 THEN 'mid' ELSE 'low' END, DATE_TRUNC('MONTH', signup_date) HAVING MAX(credit_limit) - MIN(credit_limit) > 49 ORDER BY signup_month DESC;
